sketches.source:
setcps(.1)

// One cycle is ten seconds: five in, five out
// The tone rises on the in-breath and settles on the out-breath
tone: note("[a2,e3] [f2,c3]").s("sine").attack(3).release(4).gain(.15)

// A soft rush of air on each in-breath
breath: s("pink ~").hpf(200).lpf(600).attack(4).release(5).gain(.05)

// Waves rolling in
surf: s("surf").slow(2).intensity(.4).gain(.28)

// A far-off bell every few breaths
bell: note("<a4 ~ e4 ~ c5 ~ ~ ~>").s("sine").fm(2).fmh(3.5)
  .decay(5).sustain(0).release(5).room(.8).size(.95).gain(.07)

setcpm(54/3)

// One cycle is a bar of 3/4: G D Em D C G D G
musicbox: note("<[d5 b4 g4] [a4@2 d5] [b4 g4 e4] [d4@3] [e4 g4 c5] [b4@2 g4] [a4 f#4 d4] [g4@3]>")
  .s("sine").fm(2).fmh(4)
  .attack(.002).decay(1).sustain(0).release(1.5)
  .room(.7).size(.85).gain(.2)

// A soft root on the downbeat
bass: note("<g2 d2 e2 d2 c2 g2 d2 g2>").s("triangle").timbre("soft")
  .attack(.01).decay(1).sustain(0).release(1).gain(.2)

// Someone humming along
hum: note("<g3 d3 e3 d3 c3 g3 d3 g3>").s("hum").attack(.6).release(1.5).gain(.13)

// Crickets far away
crickets: s("insect").slow(4).distance(8).gain(.07)

setcpm(56/4)

// The fire
fire: s("fire").slow(4).intensity(.3).density(6).gain(.24)

// Slow arpeggios: D, Bm, G, A
guitar: note("<[d3 a3 d4 f#4 a4 f#4 d4 a3] [b2 f#3 b3 d4 f#4 d4 b3 f#3] [g2 d3 g3 b3 d4 b3 g3 d3] [a2 e3 a3 c#4 e4 c#4 a3 e3]>")
  .s("triangle").timbre("soft")
  .attack(.005).decay(.9).sustain(0).release(1.2)
  .lpf(1600).pan(.4).room(.5).gain(.2)

// A tune hummed by the fire
hum: note("<f#4 d4 d4 c#4>").s("hum").attack(1).release(2).pan(.6).gain(.11)

// The clock on the mantel
clock: s("tick*4").lpf(3000).gain(.05)

setcpm(40/4)

// Headphones: a 2 Hz delta beat, below the 3-30 Hz range that shows a warning
drone: note("<c2 c2 ab1 bb1>").slow(2).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.32)

// A dark pad that slowly opens and closes
pad: note("[c3,g3,eb4]").slow(4).s("sawtooth").unison(4).detune(.3)
  .lpf(sine.range(300, 900).slow(16)).attack(4).release(6)
  .room(.8).size(.95).gain(.1)

// A floor of brown noise
noise: s("brown").slow(8).lpf(400).gain(.1)

// Bells far away
bells: note("<g4 ~ ~ ~ eb4 ~ ~ ~>").s("sine").fm(1.5).fmh(2)
  .decay(6).sustain(0).release(6).distance(6).gain(.08)

setcpm(30/4)

// A deep, steady blanket of brown noise
blanket: s("brown").slow(8).lpf(600).gain(.25)

// A faint airy layer on top
hush: s("pink").slow(8).hpf(1500).lpf(4000).gain(.02)

// A low hum underneath
hum: note("f1").slow(8).s("hum").gain(.1)
